def get_imports_for_annotation(anno: Any) ->ImportMap:
    imports = ImportMap()
    if is_forward_ref(anno):
        return imports
    if hasattr(anno, "__module__") and anno.__module__ is not None:
        if anno.__module__ == "typing":
            imports["typing"].add(anno.__name__)
        elif anno.__module__ != "builtins":
            imports[anno.__module__].add(anno.__name__)
    if is_generic(anno):
        for arg in getattr(anno, "__args__", []):
            if arg is not None:
                imports.merge(get_imports_for_annotation(arg))
    if is_union(anno):
        for arg in anno.__args__:
            if arg is not None:
                imports.merge(get_imports_for_annotation(arg))
    if hasattr(anno, "__origin__"):
        imports.merge(get_imports_for_annotation(anno.__origin__))
